Given,
$\begin{aligned} \mathrm{p}_{\mathrm{H}_2} & =200 \text { torr } \\ \mathrm{V}_{\mathrm{H}_2} & =100 \mathrm{~mL} \\ \mathrm{p}_{\mathrm{He}} & =100 \text { torr }\end{aligned}\begin{array}{rlrl} & \mathrm{V}_{\mathrm{He}} & =200 \mathrm{~mL} \\ & & \mathrm{n}_{\mathrm{H}_2} & =\frac{\mathrm{pV}}{\mathrm{RT}}=\frac{20000}{\mathrm{RT}} \\ \therefore & & \mathrm{n}_{\mathrm{He}} & =\frac{\mathrm{pV}}{\mathrm{RT}}=\frac{20000}{\mathrm{RT}}\end{array}
Total number of moles $=\mathrm{n}_{\mathrm{H}_2}+\mathrm{n}_{\mathrm{He}}=\frac{20000}{R T}+\frac{20000}{R T}=\frac{40000}{R T}\begin{aligned} & \text { Total volume }=300 \mathrm{~mL} \\ & \text { Total pressure }(\mathrm{p}) \quad=\frac{\mathrm{n}}{\mathrm{V}} \mathrm{RT}\end{aligned}\begin{aligned} & =\frac{40000 \times \mathrm{RT}}{\mathrm{RT} \times 300}=\frac{400}{3} \\ & =133.33 \mathrm{torr}\end{aligned}

Given,
$\begin{array}{r}\Lambda^{\circ} \mathrm{Ca}^{2+}=119 \mathrm{~S} \mathrm{~cm}^2 \mathrm{~mol}^{-1} \\ \Lambda^{\circ} \mathrm{Cl}^{-}=71 \mathrm{~S} \mathrm{~cm}^2 \mathrm{~mol}^{-1}\end{array}
As we know that,
$\begin{array}{ll} & \Lambda^{\circ} \mathrm{CaCl}_2=\Lambda_{\mathrm{Ca}^2+}^{\circ}+2 \times \Lambda^{\circ}{ }_{\mathrm{Cl}^{-}} \\ \therefore \quad & \Lambda^{\circ} \mathrm{CaCl}_2=119+2 \times 71 \\ & \Lambda^{\circ} \mathrm{CaCl}_2=261 \mathrm{~S} \mathrm{~cm}^2 \mathrm{~mol}^{-1}\end{array}
